    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: light;
        --page-bg: #f4f7fb;
        --panel-bg: rgba(255, 255, 255, 0.92);
        --panel-border: rgba(148, 163, 184, 0.18);
