        --success: #15803d;
        --shadow-lg: 0 24px 70px rgba(15, 23, 42, 0.14);
        --shadow-md: 0 16px 40px rgba(15, 23, 42, 0.1);
        --radius-xl: 28px;
        --radius-lg: 18px;
        --radius-md: 14px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top left, rgba(96, 165, 250, 0.22), transparent 32%),
          radial-gradient(circle at bottom right, rgba(129, 140, 248, 0.2), transparent 28%),
          linear-gradient(180deg, #f8fbff 0%, var(--page-bg) 100%);
        color: var(--text-primary);
      }

      .page-shell {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 40px 20px;
      }

      .support-layout {
        width: min(1120px, 100%);
        display: grid;
        grid-template-columns: minmax(280px, 1fr) minmax(360px, 520px);
        gap: 28px;
        align-items: stretch;
      }

      .hero-card,
      .form-card {
        border: 1px solid var(--panel-border);
        background: var(--panel-bg);
        backdrop-filter: blur(16px);
        border-radius: var(--radius-xl);
        box-shadow: var(--shadow-lg);
      }

      .hero-card {
        padding: 40px;
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        overflow: hidden;
        position: relative;
      }

      .hero-card::after {
        content: "";
        position: absolute;
        inset: auto -72px -72px auto;
        width: 220px;
        height: 220px;
        background: radial-gradient(circle, rgba(37, 99, 235, 0.2), transparent 68%);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        width: fit-content;
        padding: 8px 12px;
        margin-bottom: 20px;
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.72);
        color: var(--brand-strong);
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      .hero-card h1 {
        margin: 0 0 14px;
        font-size: clamp(2.2rem, 5vw, 3.8rem);
        line-height: 1.02;
        letter-spacing: -0.04em;
      }

      .hero-card p {
        margin: 0;
        max-width: 36rem;
        color: var(--text-secondary);
        font-size: 1rem;
        line-height: 1.75;
      }

      .hero-points {
        margin: 32px 0 0;
        padding: 0;
        list-style: none;
        display: grid;
        gap: 14px;
      }

      .hero-points li {
        display: flex;
        gap: 12px;
        align-items: flex-start;
        color: var(--text-secondary);
      }

      .hero-points li::before {
        content: "";
        flex: 0 0 10px;
        width: 10px;
        height: 10px;
        margin-top: 8px;
        border-radius: 999px;
        background: linear-gradient(135deg, #3b82f6, #8b5cf6);
        box-shadow: 0 0 0 6px rgba(59, 130, 246, 0.12);
      }

      .form-card {
        padding: 28px;
      }

      .form-card h2 {
        margin: 0 0 8px;
        font-size: 1.6rem;
        letter-spacing: -0.03em;
      }

      .form-intro {
        margin: 0 0 26px;
        color: var(--text-secondary);
        line-height: 1.65;
      }

      form {
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      .field-label-row {
        display: flex;
        justify-content: space-between;
        gap: 12px;
        align-items: baseline;
      }

      label {
        font-size: 0.95rem;
        font-weight: 700;
        color: var(--text-primary);
      }

      .required-badge {
        color: var(--brand-strong);
        font-size: 0.8rem;
        font-weight: 700;
      }

      .field-input {
        width: 100%;
        padding: 15px 16px;
        border: 1px solid rgba(148, 163, 184, 0.34);
        border-radius: var(--radius-md);
        background: rgba(255, 255, 255, 0.92);
        color: var(--text-primary);
        font: inherit;
        transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
      }

      .field-input::placeholder {
        color: #94a3b8;
      }

      .field-input:focus {
        outline: none;
        border-color: rgba(37, 99, 235, 0.7);
        box-shadow: 0 0 0 4px var(--brand-soft);
        transform: translateY(-1px);
      }

      .field-input[aria-invalid="true"] {
        border-color: rgba(220, 38, 38, 0.65);
        box-shadow: 0 0 0 4px rgba(220, 38, 38, 0.1);
      }

      .helper-text,
      .error-text,
      .success-banner {
        font-size: 0.9rem;
        line-height: 1.5;
      }

      .helper-text {
        color: var(--text-muted);
      }

      .error-text {
        color: var(--error);
      }

      .success-banner {
        padding: 14px 16px;
        border-radius: var(--radius-md);
        background: rgba(22, 163, 74, 0.1);
        color: var(--success);
        border: 1px solid rgba(22, 163, 74, 0.18);
      }

      .submit-button {
        margin-top: 8px;
        border: 0;
        border-radius: 999px;
        padding: 15px 22px;
        font: inherit;
        font-weight: 700;
        color: #ffffff;
        background: linear-gradient(135deg, var(--brand), #4f46e5);
        box-shadow: var(--shadow-md);
        cursor: pointer;
        transition: transform 0.18s ease, box-shadow 0.18s ease, opacity 0.18s ease;
      }

      .submit-button:hover {
        transform: translateY(-1px);
        box-shadow: 0 20px 36px rgba(37, 99, 235, 0.22);
      }

      .submit-button:active {
        transform: translateY(0);
      }

      @media (max-width: 900px) {
        .support-layout {
          grid-template-columns: 1fr;
        }

        .hero-card,
        .form-card {
          padding: 26px;
        }
      }

      @media (max-width: 520px) {
        .page-shell {
          padding: 18px;
        }

        .hero-card h1 {
          font-size: 2rem;
        }

        .field-label-row {
          flex-direction: column;
          align-items: flex-start;
          gap: 4px;
        }

        .submit-button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <div id="app"></div>
    <script>
      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        touched: {
          fullName: false,
          email: false,
          phone: false,
        },
        submitted: false,
        submittedSuccessfully: false,
      };

      const phoneHint = "Optional. Use digits with an optional country code, for example +1 555 123 4567.";

      function escapeHtml(value) {
        return String(value)
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/"/g, "&quot;")
          .replace(/'/g, "&#39;");
      }

      function validate(values) {
        const errors = {};
        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        const phonePattern = /^\+?[0-9\s().-]{7,20}$/;

        if (!values.fullName.trim()) {
          errors.fullName = "Please enter your full name.";
        }

        if (!values.email.trim()) {
          errors.email = "Please enter your email address.";
        } else if (!emailPattern.test(values.email.trim())) {
          errors.email = "Please enter a valid email address.";
        }

        if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
          errors.phone = "Please match the suggested phone number format.";
        }

        return errors;
      }

      function FormField(config) {
        const showError = Boolean(config.error) && (state.submitted || state.touched[config.name]);
        const helperMarkup = config.helperText
          ? '<div class="helper-text" id="' + config.name + '-helper">' + escapeHtml(config.helperText) + "</div>"
          : "";
        const errorMarkup = showError
          ? '<div class="error-text" id="' + config.name + '-error">' + escapeHtml(config.error) + "</div>"
          : "";
        const describedBy = [config.helperText ? config.name + "-helper" : "", showError ? config.name + "-error" : ""]
          .filter(Boolean)
          .join(" ");

        return `
          <div class="form-field">
            <div class="field-label-row">
              <label for="${config.name}">${escapeHtml(config.label)}</label>
              ${config.required ? '<span class="required-badge">Required</span>' : ""}
            </div>
            <input
              class="field-input"
              id="${config.name}"
              name="${config.name}"
              type="${config.type}"
              placeholder="${escapeHtml(config.placeholder)}"
              value="${escapeHtml(config.value)}"
              aria-invalid="${showError ? "true" : "false"}"
              ${describedBy ? 'aria-describedby="' + describedBy + '"' : ""}
              ${config.required ? "required" : ""}
            />
            ${helperMarkup}
            ${errorMarkup}
          </div>
        `;
      }

      function ContactForm() {
        const errors = validate(state.values);

        return `
          <section class="form-card">
            <h2>Contact support</h2>
            <p class="form-intro">
              Send us the basics and our support team will follow up with the right next step.
            </p>
            <form id="support-form" novalidate>
              ${state.submittedSuccessfully
                ? '<div class="success-banner" role="status">Thanks! Your support request has been captured.</div>'
                : ""}
              ${FormField({
                name: "fullName",
                label: "Full name",
                type: "text",
                placeholder: "Jordan Lee",
                required: true,
                value: state.values.fullName,
                error: errors.fullName,
              })}
              ${FormField({
                name: "email",
                label: "Email address",
                type: "email",
                placeholder: "jordan@example.com",
                required: true,
                value: state.values.email,
                error: errors.email,
              })}
              ${FormField({
                name: "phone",
                label: "Phone number",
                type: "tel",
                placeholder: "+1 555 123 4567",
                required: false,
                value: state.values.phone,
                helperText: phoneHint,
                error: errors.phone,
              })}
              <button class="submit-button" type="submit">Submit request</button>
            </form>
          </section>
        `;
      }

      function HeroPanel() {
        return `
          <section class="hero-card">
            <div>
              <div class="eyebrow">Support page</div>
              <h1>Get expert help without the back-and-forth.</h1>
              <p>
                Tell us who you are and how we can reach you. We’ll route your request to the
                right specialist so you get a faster answer.
              </p>
            </div>
            <ul class="hero-points">
              <li>Designed for quick, focused support requests.</li>
              <li>Clear required fields with optional phone follow-up.</li>
              <li>Modern product styling with calm, accessible contrast.</li>
            </ul>
          </section>
        `;
      }

      function App() {
        return `
          <main class="page-shell">
            <div class="support-layout">
              ${HeroPanel()}
              ${ContactForm()}
            </div>
          </main>
        `;
      }

      function render() {
        document.getElementById("app").innerHTML = App();
        bindEvents();
      }

      function bindEvents() {
        const form = document.getElementById("support-form");
        const inputs = form.querySelectorAll("input");

        inputs.forEach((input) => {
          input.addEventListener("input", (event) => {
            const { name, value } = event.target;
            state.values[name] = value;
            state.submittedSuccessfully = false;
            render();
          });

          input.addEventListener("blur", (event) => {
            state.touched[event.target.name] = true;
            render();
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.submitted = true;
          state.touched.fullName = true;
          state.touched.email = true;
          state.touched.phone = true;

          const errors = validate(state.values);

          if (Object.keys(errors).length === 0) {
            state.submittedSuccessfully = true;
          }

          render();
        });
      }

      render();
    </script>
  </body>
</html>
