   <body>
     <div id="app"></div>
     <script>
       const state = {
         values: {
           fullName: "",
           email: "",
           phone: "",
         },
         touched: {
           fullName: false,
           email: false,
           phone: false,
         },
         submitted: false,
         submittedSuccessfully: false,
       };

       const phoneHint = "Optional. Use digits with an optional country code, for example +1 555 123 4567.";

       function escapeHtml(value) {
         return String(value)
           .replace(/&/g, "&amp;")
           .replace(/</g, "&lt;")
           .replace(/>/g, "&gt;")
           .replace(/"/g, "&quot;")
           .replace(/'/g, "&#39;");
       }

       function validate(values) {
         const errors = {};
         const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
         const phonePattern = /^\+?[0-9\s().-]{7,20}$/;

         if (!values.fullName.trim()) {
           errors.fullName = "Please enter your full name.";
         }

         if (!values.email.trim()) {
           errors.email = "Please enter your email address.";
         } else if (!emailPattern.test(values.email.trim())) {
           errors.email = "Please enter a valid email address.";
         }

         if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
           errors.phone = "Please match the suggested phone number format.";
         }

         return errors;
       }

       function FormField(config) {
         const showError = Boolean(config.error) && (state.submitted || state.touched[config.name]);
         const helperMarkup = config.helperText
           ? '<div class="helper-text" id="' + config.name + '-helper">' + escapeHtml(config.helperText) + "</div>"
           : "";
         const errorMarkup = showError
           ? '<div class="error-text" id="' + config.name + '-error">' + escapeHtml(config.error) + "</div>"
           : "";
         const describedBy = [config.helperText ? config.name + "-helper" : "", showError ? config.name + "-error" : ""]
           .filter(Boolean)
           .join(" ");

         return `
           <div class="form-field">
             <div class="field-label-row">
               <label for="${config.name}">${escapeHtml(config.label)}</label>
               ${config.required ? '<span class="required-badge">Required</span>' : ""}
             </div>
             <input
               class="field-input"
               id="${config.name}"
               name="${config.name}"
               type="${config.type}"
               placeholder="${escapeHtml(config.placeholder)}"
               value="${escapeHtml(config.value)}"
               aria-invalid="${showError ? "true" : "false"}"
               ${describedBy ? 'aria-describedby="' + describedBy + '"' : ""}
               ${config.required ? "required" : ""}
             />
             ${helperMarkup}
             ${errorMarkup}
           </div>
         `;
       }

       function ContactForm() {
         const errors = validate(state.values);

         return `
           <section class="form-card">
             <h2>Contact support</h2>
             <p class="form-intro">
               Send us the basics and our support team will follow up with the right next step.
             </p>
             <form id="support-form" novalidate>
               ${state.submittedSuccessfully
                 ? '<div class="success-banner" role="status">Thanks! Your support request has been captured.</div>'
                 : ""}
               ${FormField({
                 name: "fullName",
                 label: "Full name",
                 type: "text",
                 placeholder: "Jordan Lee",
                 required: true,
                 value: state.values.fullName,
                 error: errors.fullName,
               })}
               ${FormField({
                 name: "email",
                 label: "Email address",
                 type: "email",
                 placeholder: "jordan@example.com",
                 required: true,
                 value: state.values.email,
                 error: errors.email,
               })}
               ${FormField({
                 name: "phone",
                 label: "Phone number",
                 type: "tel",
                 placeholder: "+1 555 123 4567",
                 required: false,
                 value: state.values.phone,
                 helperText: phoneHint,
                 error: errors.phone,
               })}
               <button class="submit-button" type="submit">Submit request</button>
             </form>
           </section>
         `;
       }

       function HeroPanel() {
         return `
           <section class="hero-card">
             <div>
               <div class="eyebrow">Support page</div>
               <h1>Get expert help without the back-and-forth.</h1>
               <p>
                 Tell us who you are and how we can reach you. We’ll route your request to the
                 right specialist so you get a faster answer.
               </p>
             </div>
             <ul class="hero-points">
               <li>Designed for quick, focused support requests.</li>
               <li>Clear required fields with optional phone follow-up.</li>
               <li>Modern product styling with calm, accessible contrast.</li>
             </ul>
           </section>
         `;
       }

       function App() {
         return `
           <main class="page-shell">
             <div class="support-layout">
               ${HeroPanel()}
               ${ContactForm()}
             </div>
           </main>
         `;
       }

       function render() {
         document.getElementById("app").innerHTML = App();
         bindEvents();
       }

       function bindEvents() {
         const form = document.getElementById("support-form");
         const inputs = form.querySelectorAll("input");

         inputs.forEach((input) => {
           input.addEventListener("input", (event) => {
             const { name, value } = event.target;
             state.values[name] = value;
             state.submittedSuccessfully = false;
             render();
           });

           input.addEventListener("blur", (event) => {
             state.touched[event.target.name] = true;
             render();
           });
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           state.submitted = true;
           state.touched.fullName = true;
           state.touched.email = true;
           state.touched.phone = true;

           const errors = validate(state.values);

           if (Object.keys(errors).length === 0) {
             state.submittedSuccessfully = true;
           }

           render();
         });
       }

       render();
     </script>
   </body>
 </html>

